import{_ as t,o as n,c as i,a2 as r}from"./chunks/framework.mRCPFc5l.js";const p=JSON.parse('{"title":"Navigation einrichten","description":"Reihenfolge und Umfang der Space-Navigation anpassen.","frontmatter":{"title":"Navigation einrichten","description":"Reihenfolge und Umfang der Space-Navigation anpassen."},"headers":[],"relativePath":"spaces/navigation.md","filePath":"spaces/navigation.md","lastUpdated":1786087067000}'),a={name:"spaces/navigation.md"};function s(o,e,l,d,g,h){return n(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="navigation-einrichten" tabindex="-1">Navigation einrichten <a class="header-anchor" href="#navigation-einrichten" aria-label="Permalink to &quot;Navigation einrichten&quot;">​</a></h1><p>Die Seitenleiste eines Space zeigt drei Bereiche: <strong>Grids</strong>, <strong>Seiten</strong> und <strong>Flows</strong>. Reihenfolge und Umfang lassen sich anpassen.</p><p>Sie finden die Einstellungen unter <strong>Space-Einstellungen → Allgemein</strong>, Abschnitt <strong>Navigation</strong>.</p><h2 id="reihenfolge-der-abschnitte" tabindex="-1">Reihenfolge der Abschnitte <a class="header-anchor" href="#reihenfolge-der-abschnitte" aria-label="Permalink to &quot;Reihenfolge der Abschnitte&quot;">​</a></h2><p>Die Einstellung heißt <strong>Abschnittsreihenfolge festlegen</strong>:</p><blockquote><p><em>Bestimmen Sie, in welcher Reihenfolge Seiten und Grids in der Navigation erscheinen sollen.</em></p></blockquote><p>Zwei Möglichkeiten:</p><table tabindex="0"><thead><tr><th>Auswahl</th><th>Reihenfolge</th></tr></thead><tbody><tr><td><strong>Grids zuerst anzeigen</strong></td><td>Grids, dann Seiten</td></tr><tr><td><strong>Seiten zuerst anzeigen</strong></td><td>Seiten, dann Grids</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">Nach der Hauptnutzung wählen</p><ul><li><strong>Grids zuerst</strong> für Spaces, in denen hauptsächlich Daten gepflegt werden.</li><li><strong>Seiten zuerst</strong> für Spaces, die vor allem <a href="/seiten/portal-veroeffentlichen">Portale</a> oder Dokumentation enthalten — dann liegt der Einstiegspunkt oben.</li></ul><p>Die Einstellung gilt für <strong>alle</strong> Personen im Space, nicht nur für Sie. Stimmen Sie sich also ab, wenn mehrere damit arbeiten.</p></div><h2 id="anzahl-sichtbarer-grids" tabindex="-1">Anzahl sichtbarer Grids <a class="header-anchor" href="#anzahl-sichtbarer-grids" aria-label="Permalink to &quot;Anzahl sichtbarer Grids&quot;">​</a></h2><p>Die Einstellung heißt <strong>Angezeigte Grids in der Navigation</strong>:</p><blockquote><p><em>Anzahl der Grids, die vor dem Einklappen angezeigt werden</em></p></blockquote><p>Voreingestellt sind <strong>10</strong>. Die übrigen verbergen sich hinter <strong>Mehr anzeigen</strong> beziehungsweise <strong>Weniger anzeigen</strong>.</p><div class="tip custom-block"><p class="custom-block-title">Bei vielen Grids niedriger setzen</p><p>Hat ein Space dreißig Grids, wird die Seitenleiste unbenutzbar lang. Ein Wert von fünf bis acht hält sie übersichtlich; der Rest bleibt über <em>Mehr anzeigen</em> erreichbar.</p><p>Welche Grids in der sichtbaren Gruppe landen, richtet sich nach der Reihenfolge in der Navigation — die wichtigsten sollten also oben stehen.</p></div><h2 id="was-in-der-navigation-unter-einem-grid-steht" tabindex="-1">Was in der Navigation unter einem Grid steht <a class="header-anchor" href="#was-in-der-navigation-unter-einem-grid-steht" aria-label="Permalink to &quot;Was in der Navigation unter einem Grid steht&quot;">​</a></h2><p>Unter jedem Grid gliedert sich die Navigation in:</p><ul><li><strong>Ansichten</strong> — alle Darstellungen dieses Grids</li><li><strong>Formulare</strong> — alle Eingabemasken dieses Grids</li></ul><p>Über <strong>Erstellen</strong> legen Sie eine <strong>Ansicht erstellen</strong> oder ein <strong>Formular erstellen</strong> an.</p><h2 id="weitere-navigationselemente" tabindex="-1">Weitere Navigationselemente <a class="header-anchor" href="#weitere-navigationselemente" aria-label="Permalink to &quot;Weitere Navigationselemente&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Element</th><th>Funktion</th></tr></thead><tbody><tr><td><strong>Alle Spaces</strong></td><td>Zurück zur Space-Übersicht</td></tr><tr><td><strong>Grids</strong> / <strong>Seiten</strong> / <strong>Flows</strong></td><td>Die drei Bereiche</td></tr><tr><td><strong>Mehr anzeigen</strong> / <strong>Weniger anzeigen</strong></td><td>Klappt die Grid-Liste auf und zu</td></tr></tbody></table><h2 id="navigation-in-veroffentlichten-portalen" tabindex="-1">Navigation in veröffentlichten Portalen <a class="header-anchor" href="#navigation-in-veroffentlichten-portalen" aria-label="Permalink to &quot;Navigation in veröffentlichten Portalen&quot;">​</a></h2><p>Für <a href="/seiten/was-sind-seiten">Seiten</a> mit Unterseiten gibt es eine eigene Einstellung: <strong>Navigation einklappbar</strong>. Sie betrifft nur die Darstellung im Portal, nicht die Space-Navigation.</p><p>→ <a href="/seiten/seite-erstellen">Seite erstellen und bearbeiten</a></p><h2 id="weiter" tabindex="-1">Weiter <a class="header-anchor" href="#weiter" aria-label="Permalink to &quot;Weiter&quot;">​</a></h2><ul><li><a href="/spaces/einstellungen">Space-Einstellungen</a></li><li><a href="/spaces/symbol-und-farbe">Symbol, Farbe und Kategorie</a></li><li><a href="/erste-schritte/oberflaeche">Die Oberfläche im Überblick</a></li></ul>',25)])])}const u=t(a,[["render",s]]);export{p as __pageData,u as default};
